b.CASE_CRE_HSE_EST_OFFC_KEY as CASE_CRE_HSE_EST_OFFC_KEY,
b.CASE_ACT_HSE_EST_OFFC_KEY as CASE_ACT_HSE_EST_OFFC_KEY
 FROM sor_cms_case a,
       sor_cms_case_sts b,
       (select z.case_key, z.case_item_key, z.RPT_CASE_TYPE_KEY, z.ACTL_CASE_TYPE_KEY 
       from sor_cms_case_item_sts z
       where to_date('$$v_rpt_date', 'yyyymmdd') between bgn_date and end_date) c 
 WHERE a.case_key = b.case_key
  AND b.CASE_CMPLT_DATE is null
and to_date('$$v_rpt_date', 'yyyymmdd') between b.bgn_date and b.end_date
   AND b.CASE_CRE_DATE < add_months(to_date('$$v_rpt_mth' || '01', 'YYYYMMDD'),1)
   AND a.case_key = c.case_key
  AND b.case_sts_code <> 'X'
 ORDER BY a.case_key;

