-- [SOURCE_QUALIFIER] Step: apply_SQ_SOR_CMS_CASE
select 
a.CASE_KEY AS CASE_KEY,
a.CMS_CASE_KEY AS CMS_CASE_KEY,
b.BGN_DATE AS BGN_DATE,
b.END_DATE AS END_DATE,
b.CUST_RQS_KEY AS CUST_RQS_KEY,
b.CASE_NUM AS CASE_NUM,
b.RPT_CMS_HSE_EST_KEY AS RPT_CMS_HSE_EST_KEY,
b.RPT_CMS_HSE_BLK_KEY AS RPT_CMS_HSE_BLK_KEY,
b.RPT_CMS_HSE_UNIT_KEY AS RPT_CMS_HSE_UNIT_KEY,
b.RPT_CASE_LOC_RMK_TEXT AS RPT_CASE_LOC_RMK_TEXT,
b.ACTL_CMS_HSE_EST_KEY AS ACTL_CMS_HSE_EST_KEY,
b.ACTL_CMS_HSE_BLK_KEY AS ACTL_CMS_HSE_BLK_KEY,
b.ACTL_CMS_HSE_UNIT_KEY AS ACTL_CMS_HSE_UNIT_KEY,
b.ACTL_CASE_LOC_RMK_TEXT AS ACTL_CASE_LOC_RMK_TEXT,
b.CASE_CRE_DATE AS CASE_CRE_DATE,
b.LAST_CASE_ACT_DATE AS LAST_CASE_ACT_DATE,
b.CASE_CMPLT_DATE AS CASE_CMPLT_DATE,
b.CASE_RMK_TEXT AS CASE_RMK_TEXT,
b.CASE_CRE_CMS_HSE_EST_KEY AS CASE_CRE_CMS_HSE_EST_KEY,
b.CASE_CRE_USER_ID AS CASE_CRE_USER_ID,
b.CASE_CRE_USER_TYPE_CODE AS CASE_CRE_USER_TYPE_CODE,
b.CASE_CRE_OFFC_TYPE_CODE AS CASE_CRE_OFFC_TYPE_CODE,
b.CASE_ACT_CMS_HSE_EST_KEY AS CASE_ACT_CMS_HSE_EST_KEY,
b.CASE_ACT_USER_ID AS CASE_ACT_USER_ID,
b.CASE_ACT_USER_TYPE_CODE AS CASE_ACT_USER_TYPE_CODE,
b.CASE_ACT_OFFC_TYPE_CODE AS CASE_ACT_OFFC_TYPE_CODE,
b.RLT_CASE_KEY AS RLT_CASE_KEY,
b.CASE_PRIOR_CODE AS CASE_PRIOR_CODE,
b.RESP_OFCR_USER_ID AS RESP_OFCR_USER_ID,
b.CASE_STS_CODE AS CASE_STS_CODE,
b.CASE_CNFRM_DATE AS CASE_CNFRM_DATE,
b.CASE_RPLY_CNT AS CASE_RPLY_CNT,
b.LAST_CASE_RPLY_DATE AS LAST_CASE_RPLY_DATE,
b.DVC_REC_TXN_ID AS DVC_REC_TXN_ID,
b.CUST_RQS_TXN_ID AS CUST_RQS_TXN_ID,
b.RLT_CASE_TXN_ID AS RLT_CASE_TXN_ID,
b.CLS_CASE_IND AS CLS_CASE_IND,
b.CASE_CRE_HSE_EST_OFFC_KEY as CASE_CRE_HSE_EST_OFFC_KEY,
b.CASE_ACT_HSE_EST_OFFC_KEY as CASE_ACT_HSE_EST_OFFC_KEY,
c.CASE_WO_KEY as CASE_WO_KEY,
d.CASE_WO_ITEM_KEY as CASE_WO_ITEM_KEY,
c.WO_SCHD_CMNC_DATE as WO_SCHD_CMNC_DATE,
c.WO_CRE_DATE as WO_CRE_DATE,
c.BGN_DATE as WO_BGN_DATE,
c.WO_RPT_CMNC_DATE as WO_RPT_CMNC_DATE,
c.WO_RPT_CMPLT_DATE as WO_RPT_CMPLT_DATE 
 FROM sor_cms_case a,
       sor_cms_case_sts b,
       (
		select 	z.CASE_WO_KEY,
				z.CASE_KEY,
				z.wo_schd_cmnc_date,
				z.wo_cre_date,
				z.bgn_date,
				z.WO_RPT_CMNC_DATE,
				z.WO_RPT_CMPLT_DATE
				from sor_cms_case_wo_sts z
				where rec_msg_type_code like 'WO%'
				and ( 
					to_char(wo_schd_cmnc_date,'yyyymm') = substr('$$v_rpt_mth',1,6 )
					or to_char(wo_cre_date,'yyyymm') = substr('$$v_rpt_mth',1,6 )
					or to_char(bgn_date,'yyyymm') = substr('$$v_rpt_mth',1,6 )
					or to_char(WO_RPT_CMNC_DATE,'yyyymm') = substr('$$v_rpt_mth',1,6 ) 
					or to_char(WO_RPT_CMPLT_DATE ,'yyyymm') = substr('$$v_rpt_mth',1,6 ) 
				) 
				AND to_date('$$v_rpt_date', 'yyyymmdd') between bgn_date and end_date
) c ,
sor_cms_case_wo_item_sts d
 WHERE a.case_key = b.case_key
and to_date('$$v_rpt_date', 'yyyymmdd') between b.bgn_date and b.end_date
   AND a.case_key = c.case_key 
  AND c.case_wo_key = d.case_wo_key 
and to_date('$$v_rpt_date', 'yyyymmdd') between d.bgn_date and d.end_date
  AND b.case_sts_code <> 'X'
 ORDER BY a.case_key;

