c.ARTSN_ORD_ISS_DATE as ARTSN_ORD_ISS_DATE
 FROM sor_cms_case a,
       sor_cms_case_sts b,
       (
		SELECT 	z.CASE_KEY,
					z.CASE_ARTSN_ORD_KEY,
					z.ARTSN_ORD_BGN_DATE,
					z.ARTSN_ORD_CMPLT_DATE,
					z.ARTSN_ORD_STS_CODE,
					z.ARTSN_ORD_ISS_DATE
		FROM 		SOR_CMS_CASE_ARTSN_ORD_STS z
		WHERE 	(
						to_char(ARTSN_ORD_ISS_DATE,'yyyymm') = substr('$$v_rpt_mth',1,6 ) 
						OR to_char(ARTSN_ORD_CMPLT_DATE,'yyyymm') = substr('$$v_rpt_mth',1,6 ) 
					)
		AND to_date('$$v_rpt_date', 'yyyymmdd') between bgn_date and end_date
		) c 
 WHERE a.case_key = b.case_key
and to_date('$$v_rpt_date', 'yyyymmdd') between b.bgn_date and b.end_date
   AND a.case_key = c.case_key 
  AND b.case_sts_code <> 'X'
 ORDER BY a.case_key;

